 private VBox passwordPanel(){VBox p=page();Label intro=new Label("Create strong passwords on this device. Strength is an estimate, not a guarantee.");intro.getStyleClass().add("muted");Slider length=new Slider(4,128,20);length.setShowTickLabels(true);length.setMajorTickUnit(20);length.setBlockIncrement(1);Label lengthLabel=new Label("Length: 20 characters");length.valueProperty().addListener((o,a,b)->lengthLabel.setText("Length: "+b.intValue()+" characters"));CheckBox upper=new CheckBox("Uppercase"),lower=new CheckBox("Lowercase"),digits=new CheckBox("Numbers"),symbols=new CheckBox("Symbols"),exclude=new CheckBox("Exclude ambiguous characters");upper.setSelected(true);lower.setSelected(true);digits.setSelected(true);symbols.setSelected(true);Spinner<Integer> amount=new Spinner<>(1,10,1);amount.setPrefWidth(90);PasswordField masked=new PasswordField();TextField visible=new TextField();masked.setPromptText("Generate a password to see it here");visible.setPromptText("Generate a password to see it here");masked.setEditable(false);visible.setEditable(false);masked.textProperty().bindBidirectional(visible.textProperty());CheckBox reveal=new CheckBox("Show password");visible.setVisible(false);visible.setManaged(false);reveal.setOnAction(e->{boolean show=reveal.isSelected();masked.setVisible(!show);masked.setManaged(!show);visible.setVisible(show);visible.setManaged(show);});StackPane output=new StackPane(masked,visible);output.getStyleClass().add("password-output");Label strength=new Label("Strength estimate: —");strength.getStyleClass().add("strength-label");ListView<PasswordHistoryEntry> history=new ListView<>();history.setPrefHeight(190);history.setPlaceholder(new Label("Generated passwords stay here temporarily, in memory only."));history.setCellFactory(v->new ListCell<>(){protected void updateItem(PasswordHistoryEntry item,boolean empty){super.updateItem(item,empty);setText(empty||item==null?null:item.time().toString()+"   ·   •••••••••••••");}});history.setTooltip(new Tooltip("Select an entry to load it into the password field."));history.getSelectionModel().selectedItemProperty().addListener((o,a,entry)->{if(entry!=null){masked.setText(entry.value());strength.setText("Strength estimate: "+passwords.estimate(entry.value()));}});Button gen=new Button("Generate password");gen.setId("primary-action");gen.getStyleClass().add("primary");Button copy=new Button("Copy password");Button clear=new Button("Clear history");copy.disableProperty().bind(masked.textProperty().isEmpty());gen.setOnAction(e->{try{int count=amount.getValue();List<String> batch=passwords.generateMultiple(count,(int)length.getValue(),upper.isSelected(),lower.isSelected(),digits.isSelected(),symbols.isSelected(),exclude.isSelected());history.getSelectionModel().clearSelection();for(String value:batch)history.getItems().add(0,new PasswordHistoryEntry(Instant.now(),value));while(history.getItems().size()>20)history.getItems().remove(20);masked.setText(batch.get(0));strength.setText("Strength estimate: "+passwords.estimate(batch.get(0)));status(count==1?"Password generated in memory only.":count+" passwords generated in memory only.");}catch(Exception x){alert(x.getMessage());}});copy.setOnAction(e->{clipboard(masked.getText());status("Password copied to clipboard.");});clear.setOnAction(e->{history.getItems().clear();masked.clear();strength.setText("Strength estimate: —");status("Temporary password history cleared from memory.");});VBox options=new VBox(10,new HBox(14,upper,lower,digits,symbols),exclude,new HBox(8,new Label("Generate at once"),amount));options.getStyleClass().add("tool-card");VBox generator=new VBox(12,lengthLabel,length,options,new HBox(10,gen,copy,reveal),output,strength);generator.getStyleClass().add("tool-card");VBox.setVgrow(history,Priority.ALWAYS);p.getChildren().addAll(sectionTitle("Password Generator"),intro,generator,sectionTitle("Temporary password history"),history);return p;}
 private VBox jsonPanel(){VBox p=page();TextArea input=editor(),output=editor();input.setPromptText("Paste or open JSON here…");output.setPromptText("Formatted output appears here");output.setEditable(false);ComboBox<Integer> spaces=new ComboBox<>();spaces.getItems().addAll(2,4,8);spaces.setValue(indent);Label counts=new Label();input.textProperty().addListener((o,a,b)->counts.setText(b.lines().count()+" lines  ·  "+b.length()+" characters"));Button format=new Button("Format"),minify=new Button("Minify"),validate=new Button("Validate"),sample=new Button("Load sample"),open=new Button("Open file"),save=new Button("Save output"),copy=new Button("Copy output"),clear=new Button("Clear");format.setId("primary-action");format.getStyleClass().add("primary");spaces.setOnAction(e->indent=spaces.getValue());format.setOnAction(e->runJson(input,output,true));minify.setOnAction(e->runJson(input,output,false));validate.setOnAction(e->{try{json.validate(input.getText());status("Valid JSON.");}catch(Exception x){alert(jsonError(x));}});sample.setOnAction(e->input.setText("{\n  \"name\": \"DevForge\",\n  \"features\": [\"passwords\", \"JSON\", \"snippets\"],\n  \"localFirst\": true\n}"));open.setOnAction(e->{FileChooser f=new FileChooser();f.getExtensionFilters().add(new FileChooser.ExtensionFilter("JSON files","*.json"));var file=f.showOpenDialog(root.getScene().getWindow());if(file!=null)try{input.setText(Files.readString(file.toPath()));}catch(Exception x){alert(x.getMessage());}});save.setOnAction(e->{if(output.getText().isBlank()){alert("Format or minify JSON first.");return;}FileChooser f=new FileChooser();f.setInitialFileName("formatted.json");var file=f.showSaveDialog(root.getScene().getWindow());if(file!=null)try{Files.writeString(file.toPath(),output.getText());status("JSON saved.");}catch(Exception x){alert(x.getMessage());}});copy.setOnAction(e->{clipboard(output.getText());status("Output copied.");});clear.setOnAction(e->{input.clear();output.clear();});FlowPane actions=new FlowPane(8,8,format,minify,validate,sample,open,save,copy,clear,new Label("Indent"),spaces);actions.setAlignment(Pos.CENTER_LEFT);HBox editors=new HBox(14,editorColumn("Input",input),editorColumn("Output",output));HBox.setHgrow(editors.getChildren().get(0),Priority.ALWAYS);HBox.setHgrow(editors.getChildren().get(1),Priority.ALWAYS);VBox.setVgrow(editors,Priority.ALWAYS);p.getChildren().addAll(sectionTitle("JSON Formatter"),actions,counts,editors);return p;}
 private void runJson(TextArea input,TextArea output,boolean pretty){try{output.setText(pretty?json.format(input.getText(),indent):json.minify(input.getText()));db.activity(pretty?"Formatted JSON":"Minified JSON");status(pretty?"JSON formatted.":"JSON minified.");}catch(Exception e){alert(jsonError(e));}}
 private String jsonError(Exception e){String m=e.getMessage();return m==null?"Invalid JSON.":m.replaceAll("\\s*\\n.*"," ").replace("com.fasterxml.jackson.core.","");}
 private VBox snippetPanel()throws SQLException{VBox p=page();TextField search=new TextField();search.setId("module-search");search.setPromptText("Search snippets");ComboBox<String> lang=new ComboBox<>(),category=new ComboBox<>(),sort=new ComboBox<>();lang.getItems().addAll("All","Java","JavaScript","Python","SQL","Other");lang.setValue("All");category.getItems().addAll("All","Utilities","Frontend","Backend","Database","Other");category.setValue("All");sort.getItems().addAll("Updated","Created","Title");sort.setValue("Updated");ListView<Snippet> list=new ListView<>();list.setCellFactory(v->new ListCell<>(){protected void updateItem(Snippet s,boolean empty){super.updateItem(s,empty);setText(empty||s==null?null:(s.favorite()?"★ ":"")+s.title()+"   ·   "+s.language());}});TextField title=new TextField(),description=new TextField(),language=new TextField(),cat=new TextField(),tags=new TextField();TextArea code=editor();title.setPromptText("Title");description.setPromptText("Description");language.setPromptText("Language");cat.setPromptText("Category");tags.setPromptText("Tags, comma-separated");Button add=new Button("New"),save=new Button("Save snippet"),del=new Button("Delete"),fav=new Button("Toggle favorite"),copy=new Button("Copy code"),imp=new Button("Import JSON"),exp=new Button("Export JSON");
  Runnable refresh=()->{try{list.getItems().setAll(db.snippets(search.getText(),lang.getValue(),category.getValue(),sort.getValue()));}catch(SQLException e){error("Could not load snippets",e);}};search.textProperty().addListener((o,a,b)->refresh.run());lang.setOnAction(e->refresh.run());category.setOnAction(e->refresh.run());sort.setOnAction(e->refresh.run());list.getSelectionModel().selectedItemProperty().addListener((o,a,s)->{if(s!=null){title.setText(s.title());description.setText(s.description());language.setText(s.language());cat.setText(s.category());tags.setText(s.tags());code.setText(s.code());}});add.setOnAction(e->{list.getSelectionModel().clearSelection();title.clear();description.clear();language.clear();cat.clear();tags.clear();code.clear();});save.setOnAction(e->{if(title.getText().isBlank()||code.getText().isBlank()){alert("Title and code are required.");return;}Snippet old=list.getSelectionModel().getSelectedItem();Snippet s=old==null?Snippet.create(title.getText().trim(),description.getText(),language.getText(),code.getText(),cat.getText(),tags.getText()):new Snippet(old.id(),title.getText().trim(),description.getText(),language.getText(),code.getText(),cat.getText(),tags.getText(),old.favorite(),old.createdAt(),Instant.now());try{db.save(s);db.activity(old==null?"Created snippet: "+s.title():"Edited snippet: "+s.title());refresh.run();status("Snippet saved.");}catch(SQLException x){error("Could not save snippet",x);}});del.setOnAction(e->{Snippet s=list.getSelectionModel().getSelectedItem();if(s==null)return;if(confirm("Delete snippet ‘"+s.title()+"’?"))try{db.delete(s.id());db.activity("Deleted snippet: "+s.title());refresh.run();add.fire();}catch(SQLException x){error("Could not delete snippet",x);}});fav.setOnAction(e->{Snippet s=list.getSelectionModel().getSelectedItem();if(s!=null)try{db.save(new Snippet(s.id(),s.title(),s.description(),s.language(),s.code(),s.category(),s.tags(),!s.favorite(),s.createdAt(),Instant.now()));refresh.run();}catch(SQLException x){error("Could not update favorite",x);}});copy.setOnAction(e->clipboard(code.getText()));imp.setOnAction(e->importSnippets(refresh));exp.setOnAction(e->exportSnippets());FlowPane actions=new FlowPane(8,8,add,save,del,fav,copy,imp,exp);actions.setAlignment(Pos.CENTER_LEFT);VBox details=new VBox(8,title,description,language,cat,tags,code,actions);VBox.setVgrow(code,Priority.ALWAYS);VBox listbox=new VBox(8,new HBox(8,search,lang,category,sort),list);HBox content=new HBox(14,listbox,details);HBox.setHgrow(listbox,Priority.SOMETIMES);HBox.setHgrow(details,Priority.ALWAYS);VBox.setVgrow(content,Priority.ALWAYS);refresh.run();p.getChildren().addAll(sectionTitle("Snippet Manager"),content);return p;}
 private void importSnippets(Runnable refresh){FileChooser f=new FileChooser();f.getExtensionFilters().add(new FileChooser.ExtensionFilter("JSON","*.json"));var file=f.showOpenDialog(root.getScene().getWindow());if(file==null)return;try{Snippet[] items=new ObjectMapper().readValue(file,Snippet[].class);for(Snippet s:items)db.save(s);db.activity("Imported "+items.length+" snippets");refresh.run();status("Imported "+items.length+" snippets.");}catch(Exception e){alert("Import failed: "+e.getMessage());}}
 private void exportSnippets(){try{List<Snippet> items=db.snippets("","All","All","Updated");FileChooser f=new FileChooser();f.setInitialFileName("devforge-snippets.json");var file=f.showSaveDialog(root.getScene().getWindow());if(file!=null){new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(file,items);status("Snippets exported.");}}catch(Exception e){alert("Export failed: "+e.getMessage());}}
 private VBox readmePanel(){VBox p=page();readmeFields.clear();String[][] fields={{"Project name","My Project"},{"Short description",""},{"Project overview",""},{"Features",""},{"Technologies used",""},{"Prerequisites",""},{"Installation steps",""},{"Usage instructions",""},{"Project structure",""},{"Screenshots or image paths",""},{"Contribution guidelines",""},{"License","MIT"},{"Author or maintainer",""},{"Contact or repository links",""}};GridPane form=new GridPane();form.setHgap(10);form.setVgap(8);int i=0;for(String[] f:fields){Label l=new Label(f[0]);TextField input=new TextField(f[1]);input.setMaxWidth(Double.MAX_VALUE);input.setPromptText(f[0]);readmeFields.put(f[0],input);form.add(l,i%2*2,(i/2));form.add(input,i%2*2+1,(i/2));GridPane.setHgrow(input,Priority.ALWAYS);i++;}TextArea md=editor();md.setEditable(true);md.setPrefRowCount(20);preview=new VBox(12);preview.getStyleClass().add("markdown-preview");ScrollPane previewScroll=new ScrollPane(preview);previewScroll.setFitToWidth(true);previewScroll.setMinHeight(300);boolean[] loadedReadme={false};Button generate=new Button("Generate preview"),copy=new Button("Copy Markdown"),save=new Button("Save README.md"),load=new Button("Load README");generate.getStyleClass().add("primary");Runnable make=()->{Map<String,String> vals=new LinkedHashMap<>();readmeFields.forEach((k,v)->vals.put(k,v.getText()));md.setText(readmes.generate(vals));};md.textProperty().addListener((o,a,b)->renderMarkdownPreview(b));generate.setOnAction(e->{loadedReadme[0]=false;make.run();try{db.activity("Generated README Markdown");status("README generated and preview updated.");}catch(SQLException x){error("Could not record activity",x);}});for(TextField tf:readmeFields.values())tf.textProperty().addListener((o,a,b)->{if(!loadedReadme[0])make.run();});copy.setOnAction(e->{clipboard(md.getText());status("Markdown copied.");});save.setOnAction(e->{if(md.getText().isBlank()){alert("Generate or load a README before saving.");return;}FileChooser f=new FileChooser();f.setInitialFileName("README.md");var file=f.showSaveDialog(root.getScene().getWindow());if(file!=null)try{Files.writeString(file.toPath(),md.getText());status("README.md saved.");}catch(Exception x){alert(x.getMessage());}});load.setOnAction(e->{FileChooser f=new FileChooser();var file=f.showOpenDialog(root.getScene().getWindow());if(file!=null)try{String contents=Files.readString(file.toPath());md.setText(contents);loadedReadme[0]=true;status("README loaded. Edit the Markdown, or generate a new one from the form.");}catch(Exception x){alert("Could not load README: "+x.getMessage());}});make.run();HBox editors=new HBox(12,editorColumn("Markdown · editable",md),editorColumn("Rendered preview",previewScroll));HBox.setHgrow(editors.getChildren().get(0),Priority.ALWAYS);HBox.setHgrow(editors.getChildren().get(1),Priority.ALWAYS);VBox.setVgrow(md,Priority.ALWAYS);VBox.setVgrow(previewScroll,Priority.ALWAYS);VBox.setVgrow(editors,Priority.ALWAYS);p.getChildren().addAll(sectionTitle("README Maker"),form,new HBox(8,generate,copy,save,load),editors);return p;}
 private void renderMarkdownPreview(String markdown){if(preview==null)return;preview.getChildren().clear();org.commonmark.node.Node document=org.commonmark.parser.Parser.builder().build().parse(markdown);appendMarkdownBlocks(document,preview);if(preview.getChildren().isEmpty()){Label empty=new Label("Your rendered README preview will appear here.");empty.getStyleClass().add("muted");preview.getChildren().add(empty);}}
 private void appendMarkdownBlocks(org.commonmark.node.Node parent,VBox target){for(org.commonmark.node.Node child=parent.getFirstChild();child!=null;child=child.getNext()){if(child instanceof org.commonmark.node.Heading heading){TextFlow flow=markdownFlow(heading,"markdown-heading markdown-h"+heading.getLevel());target.getChildren().add(flow);}else if(child instanceof org.commonmark.node.Paragraph paragraph){target.getChildren().add(markdownFlow(paragraph,"markdown-paragraph"));}else if(child instanceof org.commonmark.node.FencedCodeBlock code){target.getChildren().add(markdownCode(code.getLiteral()));}else if(child instanceof org.commonmark.node.IndentedCodeBlock code){target.getChildren().add(markdownCode(code.getLiteral()));}else if(child instanceof org.commonmark.node.BulletList list){target.getChildren().add(markdownList(list,false));}else if(child instanceof org.commonmark.node.OrderedList list){target.getChildren().add(markdownList(list,true));}else if(child instanceof org.commonmark.node.BlockQuote quote){VBox block=new VBox(6);block.getStyleClass().add("markdown-quote");appendMarkdownBlocks(quote,block);target.getChildren().add(block);}else if(child instanceof org.commonmark.node.ThematicBreak){Separator rule=new Separator();rule.getStyleClass().add("markdown-rule");target.getChildren().add(rule);}else if(child instanceof org.commonmark.node.HtmlBlock html){Label safeText=new Label(html.getLiteral());safeText.setWrapText(true);safeText.getStyleClass().add("markdown-raw");target.getChildren().add(safeText);}else if(child.getFirstChild()!=null){VBox nested=new VBox(6);appendMarkdownBlocks(child,nested);target.getChildren().add(nested);}}}
 private VBox markdownList(org.commonmark.node.Node list,boolean ordered){VBox result=new VBox(6);result.getStyleClass().add("markdown-list");int number=1;for(org.commonmark.node.Node item=list.getFirstChild();item!=null;item=item.getNext()){if(!(item instanceof org.commonmark.node.ListItem))continue;String markerText=ordered?number+".":"•";if(ordered)number++;Label marker=new Label(markerText);marker.getStyleClass().add("markdown-list-marker");VBox contents=new VBox(6);appendMarkdownBlocks(item,contents);HBox row=new HBox(8,marker,contents);row.setAlignment(Pos.TOP_LEFT);result.getChildren().add(row);}return result;}
 private VBox markdownCode(String content){TextArea code=new TextArea(content);code.setEditable(false);code.setWrapText(false);code.getStyleClass().add("markdown-code-block");int rows=(int)Math.max(2,Math.min(10,content.lines().count()+1));code.setPrefRowCount(rows);return new VBox(code);}
 private TextFlow markdownFlow(org.commonmark.node.Node block,String styleClass){TextFlow flow=new TextFlow();flow.getStyleClass().add("markdown-flow");flow.getStyleClass().addAll(styleClass.split(" "));for(org.commonmark.node.Node child=block.getFirstChild();child!=null;child=child.getNext())appendMarkdownInline(child,flow,"");return flow;}
 private void appendMarkdownInline(org.commonmark.node.Node node,TextFlow flow,String styles){if(node instanceof org.commonmark.node.Text text){addMarkdownText(flow,text.getLiteral(),styles);return;}if(node instanceof org.commonmark.node.Code code){addMarkdownText(flow,code.getLiteral(),(styles+" markdown-code-inline").trim());return;}if(node instanceof org.commonmark.node.HtmlInline html){addMarkdownText(flow,html.getLiteral(),(styles+" markdown-raw").trim());return;}if(node instanceof org.commonmark.node.SoftLineBreak||node instanceof org.commonmark.node.HardLineBreak){addMarkdownText(flow,"\n",styles);return;}if(node instanceof org.commonmark.node.Image image){addMarkdownText(flow,"[Image: "+markdownPlainText(image)+"]",(styles+" markdown-image").trim());return;}String nested=styles;if(node instanceof org.commonmark.node.Emphasis)nested=(nested+" markdown-italic").trim();if(node instanceof org.commonmark.node.StrongEmphasis)nested=(nested+" markdown-strong").trim();if(node instanceof org.commonmark.node.Link)nested=(nested+" markdown-link").trim();for(org.commonmark.node.Node child=node.getFirstChild();child!=null;child=child.getNext())appendMarkdownInline(child,flow,nested);}
 private String markdownPlainText(org.commonmark.node.Node node){StringBuilder text=new StringBuilder();for(org.commonmark.node.Node child=node.getFirstChild();child!=null;child=child.getNext()){if(child instanceof org.commonmark.node.Text value)text.append(value.getLiteral());else if(child instanceof org.commonmark.node.Code value)text.append(value.getLiteral());else text.append(markdownPlainText(child));}return text.toString();}
 private void addMarkdownText(TextFlow flow,String value,String styles){Text text=new Text(value);text.getStyleClass().add("markdown-text");if(!styles.isBlank())text.getStyleClass().addAll(styles.split(" "));flow.getChildren().add(text);}
 private VBox settingsPanel()throws SQLException{VBox p=page();ComboBox<String> themeBox=new ComboBox<>();themeBox.getItems().addAll("dark","light");themeBox.setValue(theme);ComboBox<Integer> indentBox=new ComboBox<>();indentBox.getItems().addAll(2,4,8);indentBox.setValue(indent);CheckBox confirmBox=new CheckBox("Confirm destructive actions");confirmBox.setSelected(Boolean.parseBoolean(db.setting("confirm","true")));Label about=new Label("DevForge 1.0.0  ·  Forge Better Code.\nLocal-first developer productivity toolkit. Data is stored in your per-user AppData folder; no analytics or network services.");ListView<String> history=new ListView<>();history.getItems().setAll(db.history());Button clear=new Button("Clear activity history"),reset=new Button("Reset settings");themeBox.setOnAction(e->{theme=themeBox.getValue();try{db.setSetting("theme",theme);applyTheme(root.getScene());}catch(SQLException x){error("Could not save theme",x);}});indentBox.setOnAction(e->{indent=indentBox.getValue();try{db.setSetting("indent",String.valueOf(indent));}catch(SQLException x){error("Could not save indentation",x);}});confirmBox.setOnAction(e->{try{db.setSetting("confirm",String.valueOf(confirmBox.isSelected()));}catch(SQLException x){error("Could not save preference",x);}});clear.setOnAction(e->{if(confirm("Clear all activity history?"))try{db.clearHistory();history.getItems().clear();status("Activity history cleared.");}catch(SQLException x){error("Could not clear history",x);}});reset.setOnAction(e->{try{db.setSetting("theme","dark");db.setSetting("indent","2");db.setSetting("confirm","true");theme="dark";indent=2;applyTheme(root.getScene());themeBox.setValue(theme);indentBox.setValue(indent);confirmBox.setSelected(true);status("Settings reset to defaults.");}catch(SQLException x){error("Could not reset settings",x);}});p.getChildren().addAll(sectionTitle("Preferences"),new HBox(12,new Label("Theme"),themeBox,new Label("JSON indentation"),indentBox),confirmBox,new HBox(8,reset),sectionTitle("About"),about,sectionTitle("Activity history"),history,new HBox(8,clear));return p;}
 private void applyTheme(Scene scene){if(scene==null)return;scene.getRoot().getStyleClass().removeAll("dark","light");scene.getRoot().getStyleClass().add(theme);}
 private VBox page(){VBox p=new VBox(compact?14:18);p.setPadding(compact?new Insets(14,22,18,22):new Insets(20,22,26,22));p.getStyleClass().add("workspace");return p;}
 private void setPage(VBox p){ScrollPane scroll=new ScrollPane(p);scroll.setFitToWidth(true);scroll.getStyleClass().add("scroll-pane");Canvas backdrop=new Canvas();backdrop.setMouseTransparent(true);StackPane layered=new StackPane(backdrop,scroll);layered.getStyleClass().add("workspace-shell");backdrop.widthProperty().bind(layered.widthProperty());backdrop.heightProperty().bind(layered.heightProperty());Runnable redraw=()->drawBackdrop(backdrop);backdrop.widthProperty().addListener((o,a,b)->redraw.run());backdrop.heightProperty().addListener((o,a,b)->redraw.run());root.setCenter(layered);Platform.runLater(redraw);}
